def webp_size(file_path: Path):
    try:
        from PIL import Image
        with Image.open(file_path) as im: return im.size
    except ImportError:
        data = file_path.read_bytes()[:64]
        chunk = data[12:16]
        if chunk == b'VP8 ':
            w, h = struct.unpack_from('<HH', data, 26)
            return w & 0x3fff, h & 0x3fff
        if chunk == b'VP8L':
            bits = struct.unpack_from('<I', data, 21)[0]
            return (bits & 0x3fff) + 1, ((bits >> 14) & 0x3fff) + 1
        if chunk == b'VP8X':
            w = int.from_bytes(data[24:27], 'little') + 1
            h = int.from_bytes(data[27:30], 'little') + 1
            return w, h
        raise ValueError(f'Unsupported image header in {file_path}')

