    html+='<div class="client-grid">'+''.join(f'<article class="client-card {key}"><div class="client-photo">{image(asset,name+" · "+t("官方品牌图","official brand imagery"))}</div><div class="client-caption"><div><p class="eyebrow">{industry}</p><h3><a href="{link}" target="_blank" rel="noopener">{name} ↗</a></h3></div>{letour_logo if key=="letour" else ""}</div></article>' for name,link,asset,industry,key in clients)+'</div>'
    journey=[(t('拢齐事实','Gather facts'),t('核准产品动态、核心数据与表达边界','Lock product updates, numbers and claims'),'source'),(t('按渠道重构','Reshape per feed'),t('重写开场钩子、段落节奏与配图尺寸','Rewrite hooks, structure and visual ratios'),'channels'),(t('逐字审校','Audit & refine'),t('排查事实偏差、推广腔调与社区禁忌','Verify facts, strip hype and check taboos'),'review'),(t('沉淀复用','Carry forward'),t('归档成稿与品牌规则，喂给下一轮创作','Save approved drafts and rules for next run'),'memory')]
    icons={'source':'<rect x="6" y="3" width="13" height="19" rx="2"/><path d="M9 8h7M9 12h7M9 16h4"/>','channels':'<rect x="2" y="4" width="8" height="12" rx="2"/><rect x="14" y="8" width="8" height="12" rx="2"/><path d="M12 2v4M2 20h8"/>','review':'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6M7 10l2 2 4-4"/>','memory':'<path d="M5 7a8 8 0 1 1-1 9M5 2v5H0"/><path d="M12 7v5l3 2"/>'}
    html+=f'<div class="journey-heading"><h3>{t("一条内容发出前必经的四道关卡","Four checkpoints behind every published post")}</h3><span class="eyebrow">{t("跨行业任务拆解","Task analysis")}</span></div><ol class="journey-visual">'+''.join(f'<li><div class="journey-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{icons[key]}</svg><span>0{i+1}</span></div><h4>{title}</h4><p>{copy}</p></li>' for i,(title,copy,key) in enumerate(journey))+'</ol>'+end
    html+=start(5)+head(5,t('把访谈记录摊开对照，三句原话反复撞在一起：“每次开新窗口都得把品牌重讲一遍”、“每个平台都得单独拆改”、“最后发布那一下，说死也不敢让机器替我按”。这三处真实心理防线，直接转译成了 Finfold 的三条交互准则。','When we laid interview notes side by side, three remarks kept echoing: having to re-introduce the brand in every fresh chat, rewriting structure channel by channel, and refusing to let an algorithm press publish on a real account. Those three human boundaries became Finfold’s three design principles.'))
    insights=[(t('品牌背景只交代一次','Introduce the brand once'),t('“每次都得从头讲”','“I start from scratch every time”'),t('把定位、受众、语气与禁用词存成可见记忆，下次开工自动挂载','Store positioning, voice and banned terms in visible memory for every run')),(t('渠道差异摊在台面上','Put channel differences in plain view'),t('“每个平台都要单独改”','“Every channel needs its own pass”'),t('告别滚屏就丢的聊天流，按平台独立成卡，改哪篇看哪篇','Replace scrolling chat threads with independent per-channel cards')),(t('发布拍板留在人手里','Keep the publish button human'),t('“最后一下我得自己按”','“I want to press the last button”'),t('AI 止步于起草与自检，人工审校与发布交接边界清晰可见','AI drafts and checks; human review and publishing handoff stay explicit'))]
    html+='<div class="insight-grid illustrated">'+''.join(f'<article class="insight"><div class="insight-art art-{i}" aria-hidden="true"></div><div class="insight-copy"><span class="eyebrow">0{i+1} / {subtitle}</span><h3>{title}</h3><p>{decision}</p></div></article>' for i,(title,subtitle,decision) in enumerate(insights))+'</div>'+end
    html+=start(6)+head(6,t('拆开旧工作方式，一次发布散成六件杂活，人要在聊天窗口、文档、画布和表格之间来回横跳——为什么不用现成的聊天界面？因为六个平台意味着六个并行状态的对象，线性对话流一滚屏就把前几篇淹没了。<br><br>我把主干流程收束为三步，让品牌记忆在底层全程贯通；同时重做了屏幕空间配比：早期原型把“素材、平台、结果”机械地三等分，真正需要逐字挑错的草稿反而被挤成一条窄缝。新版将输入与渠道合进左侧栏，把最大一整块阅读区还给审稿人。','Previously, one launch fractured into six scattered chores across chat tabs, docs and spreadsheets. Why not build another chat UI? Because six channels produce six parallel objects with independent states—a linear chat stream buries earlier drafts the moment you revise.<br><br>I compressed the workflow into three stages backed by persistent brand memory, and rebalanced the viewport to match. Our first prototype split source, channels and outputs into three equal columns, squeezing the draft—the exact text a human must proofread word by word—into a narrow strip. Merging setup controls on the left gave the draft the room careful editing demands.'))
    fragments=t(['提炼核心卖点','重讲品牌背景','逐个平台起草','改尺寸配视觉','来回核对改稿','手动回收反馈'],['Extract angle','Re-brief brand','Draft per feed','Resize visuals','Cross-check copy','Log performance'])
    stages=[(t('带入素材','Bring the brief'),t('产品更新 · 自动挂载品牌记忆','Product update · Brand memory attached')),(t('分渠道成稿','Shape per channel'),t('按平台骨架生成 · 单卡独立精修','Native structure · Independent edits')),(t('审校与交接','Review & hand off'),t('人工拍板确认 · 归档至内容库','Human sign-off · Saved to library'))]
    html+=f'<div class="workflow-evolution" id="workflow"><div class="workflow-before"><div class="flow-caption"><span class="eyebrow">{t("原有碎片化做法","Fragmented workflow")}</span><h3>{t("六件杂活，跨工具来回横跳","Six chores across scattered tabs")}</h3></div><ol class="fragment-list">'+''.join(f'<li><span>0{i+1}</span>{label}</li>' for i,label in enumerate(fragments))+f'</ol></div><div class="workflow-after"><div class="flow-caption"><span class="eyebrow">{t("Finfold 空间工作流","The Finfold workflow")}</span><h3>{t("三步跑通，拍板权始终在人","Three connected stages, human sign-off")}</h3></div><ol class="connected-flow">'+''.join(f'<li><span class="flow-step">0{i+1}</span><h4>{label}</h4><p>{detail}</p></li>' for i,(label,detail) in enumerate(stages))+f'</ol><div class="context-rail"><span aria-hidden="true">↺</span><strong>{t("可编辑品牌记忆贯穿全程","Editable brand memory runs underneath")}</strong><span>{t("定位 / 受众 / 语气 / 禁用词 / 范文","Positioning / Audience / Voice / Banned terms / Examples")}</span></div></div></div>'
    def wire(new):
        blocks=t(['导航','素材与平台','内容预览'] if new else ['导航','素材','平台','结果'],['Nav','Source + channels','Draft canvas'] if new else ['Nav','Source','Channels','Outputs'])
        return '<div class="wire '+('new' if new else '')+'">'+''.join(f'<div>{b}<div class="lines"></div><div class="lines"></div><div class="lines"></div></div>' for b in blocks)+'</div>'
    html+=f'<div class="wire-grid"><div><p class="wire-label"><span>{t("早期布局原型","Early layout")}</span><span>01</span></p>{wire(False)}<p class="wire-caption">{t("三栏机械平分宽度，真正要逐字审读的草稿被挤成窄条","Three equal columns squeezed the proofread draft into a cramped strip")}</p></div><div><p class="wire-label"><span>{t("重构后空间配比","Shipped layout")}</span><span>02</span></p>{wire(True)}<p class="wire-caption">{t("输入与渠道收进左侧控制栏，把整块安静画布留给草稿审校","Setup controls share one rail; the draft gets a full reading canvas")}</p></div></div>'+end
    html+=start(7,True)+head(7,t('市面上不少 AI 工具热衷用高饱和霓虹渐变与发光边框强调“科技感”；但在内容审校台里，视觉炫技只会跟文字抢注意力。“雾白”与“石墨”两套主题共用同一套克制层级：微透玻璃材质严格锁在导航与外围控件区，正文表面保持像纸张一样平实安静——因为用户要在这里逐字核对价格、推敲分寸。','Many AI tools lean on neon gradients and glowing borders to advertise “intelligence.” Inside an editing workspace, visual theatrics fight the reader’s eye. Mist and Graphite themes share one disciplined hierarchy: subtle glass stays strictly in navigation chrome, while the draft surface remains flat and calm—because this is where people check prices and weigh phrasing word by word.'))
    gallery=[('agent',t('智能体','Agent'),'agent-'+short+'-dark',t('一句意图输入 + 三个高频任务入口，降低冷启动门槛','One prompt bar and three familiar starting tasks—zero cold-start overload')),
      ('studio',t('创作台','Content kit'),mainshot,t('左侧锁定素材与渠道，右侧并排审阅多平台成稿','Source and channels on one rail; channel variants ready for review')),
      ('overview',t('增长总览','Overview'),'overview-'+short+'-dark',t('聚合真实账号趋势、阶段目标与下一步选题建议','Real account trends, goals and next-step recommendations'))]
    if not en: gallery.append(('library','内容库','library-zh-dark','按状态沉淀历史内容包，随时找回上下文重编'))
    html+='<div class="gallery-tabs" role="tablist" aria-label="'+t('产品界面','Product screens')+'">'+''.join(f'<button id="tab-{key}" role="tab" aria-selected="{str(i==0).lower()}" aria-controls="panel-{key}" tabindex="{0 if i==0 else -1}">{label}</button>' for i,(key,label,_,__) in enumerate(gallery))+'</div>'
    html+=''.join(f'<div class="gallery-panel" id="panel-{key}" role="tabpanel" aria-labelledby="tab-{key}"{ " hidden" if i else ""}>{image(asset,label+" · "+t("深色界面","dark theme"))}<p class="screen-caption"><span>{caption}</span><span>0{i+1} / 0{len(gallery)}</span></p></div>' for i,(key,label,asset,caption) in enumerate(gallery))
    html+=f'<div class="design-system"><div><p class="eyebrow">{t("视觉与排版系统","Visual & typographic system")}</p><h3>{t("克制的环境光<br>与纸面级的阅读定力","Calm ambient surfaces<br>built for close proofreading")}</h3><p>{t("砍掉冗余分割线与刺眼强调色，仅靠留白尺度、字重对比与低饱和灰绿引导操作优先级。","Fewer heavy borders and competing accents—relying on spatial cadence, type weight and muted sage to signal priority.")}</p><div class="swatches" aria-label="{t("雾白、浅灰绿、石墨、灰绿配色","Mist, pale sage, graphite, and muted green palette")}"><span class="swatch" style="background:#f0f3f2"></span><span class="swatch" style="background:#dce5df"></span><span class="swatch" style="background:#202629"></span><span class="swatch" style="background:#89bcb1"></span></div><div class="type-specimen"><strong>{t("字 01","Aa 01")}</strong><span>{t("审读优先<br>数字等宽醒目，正文久看不累","Proofreading first<br>Crisp numerals, low-fatigue body copy")}</span></div></div><div><div class="theme-tabs" role="tablist" aria-label="{t("主题预览","Theme preview")}"><button id="theme-light" role="tab" aria-selected="true" aria-controls="theme-panel-light">{t("雾白","Mist")}</button><button id="theme-dark" role="tab" aria-selected="false" aria-controls="theme-panel-dark" tabindex="-1">{t("石墨","Graphite")}</button></div><div class="theme-preview" role="tabpanel" id="theme-panel-light" aria-labelledby="theme-light">{image("agent-"+short+"-light",t("智能体 · 雾白主题","Agent · mist theme"))}</div><div class="theme-preview" role="tabpanel" id="theme-panel-dark" aria-labelledby="theme-dark" hidden>{image("agent-"+short+"-dark",t("智能体 · 石墨主题","Agent · graphite theme"))}</div></div></div>'+end
    html+=start(8)+head(8,t('今天让大模型吐出几段通顺文字已经毫无门槛；真正拉开体验差距的，是权责边界怎么划——规则在哪一步介入、多平台怎样变奏而不走样、模型搞砸时怎么向用户交底。这一章记录几次关键取舍，包括我亲手砍掉的两处“路演加分项”。','Getting an LLM to generate fluent paragraphs is effortless now. What separates a toy from a workhorse is where you draw the boundaries: when constraints step in, how structure bends without warping facts, and how the UI behaves when models fail. Here are those concrete calls—including two “demo pleasers” I deleted myself.'))
    html+=f'<article class="memory-study" id="brand-context"><div class="case-subhead"><span class="eyebrow">01 / {t("上下文前置架构","Pre-generation context")}</span><h3>{t("别等十一篇全写完，才弹窗说语气错了","Move brand rules upstream—before a word is written")}</h3><p>{t("早期版本把品牌检查放在最后：等 11 份平台草稿浩浩荡荡全部生成完，系统才跳出提示“语气可能与品牌不符”。判断没毛病，时机太致命——用户已经等完一轮、甚至动手改了几段，事后报错等于罚人推倒重来。后来我把约束彻底前移：品牌标准拼写、严禁改动的数字、行业禁用词先注入生成上下文，落笔后再做二次校验。","Early on, the brand check ran last: all eleven drafts finished generating before the system warned that tone might be off. Accurate warning, terrible timing—people had already waited and started editing, making a redo feel like punishment. So I moved rules upstream: exact brand spelling, immutable numbers and banned words enter context before generation, then run a verification pass after.")}</p></div><div class="memory-evidence">{image("memory-"+short+"-light",t("品牌记忆 · 实际保存的个人与品牌资料","Brand memory · saved personal and brand context"))}</div><div class="memory-reasoning"><div><span class="eyebrow">{t("真实保存的表达原则","Saved voice principle")}</span><blockquote>{t("清楚、可信、不过度承诺","Clear, credible, without overpromising")}</blockquote><span class="memory-owner">{t("赵越","Joey Zhao")} · {t("个人 + 品牌记忆实例","Live personal + brand profile")}</span></div><div><h4>{t("为什么拆成两个地方存","Why separate memory from brief")}</h4><p>{t("品牌定位与禁用词一存管几个月，而版本更新素材每次都在换。把长效记忆与单次素材在架构上拆开，既免去每次重复粘贴背景，也让用户随时点开就能看清 AI 下笔时到底受哪些规则约束。","Brand positioning and banned words hold steady for months; launch notes change every session. Splitting persistent memory from the per-task brief stops repetitive pasting and keeps the AI’s active rules inspectable.")}</p></div></div></article>'
    html+=f'<article class="channel-study" id="channels"><div class="case-subhead"><span class="eyebrow">02 / {t("跨平台叙事重构","Structural adaptation")}</span><h3>{t("锁死同一组事实，换掉整副开场骨架","Same underlying facts, completely different hooks")}</h3><p>{t("跨渠道适配绝非“把长文截成短文”。以下两份草稿取自同一份真实保存的内容包（中文版为对照译文），看同一句产品事实如何按社区语感重写开场。","Channel adaptation is never mere word-count truncation. Pulled from the same saved content kit, compare how one factual brief restructures its opening spine for X versus LinkedIn.")}</p></div><div class="source-brief"><span class="eyebrow">{t("原始素材节选","Source excerpt")}</span><p>{t("Finfold 帮助独立创始人与小团队，把一次产品更新转成适合不同平台的内容草稿。","Finfold helps solo founders and small teams turn one product update into platform-specific content drafts.")}</p><div class="source-tags"><span>{t("同一条产品更新","One product update")}</span><span>{t("两套社区语境","Two distinct feeds")}</span><span>{t("事实与审校共享","Shared facts & review")}</span></div></div><div class="channel-branches" aria-hidden="true"><span>↙</span><span>↘</span></div><div class="channel-comparison"><article class="channel-draft"><div class="draft-top"><span class="channel-mark">𝕏</span><strong>X / Twitter</strong><span class="draft-label">{t("草稿译文","Draft excerpt")}</span></div><blockquote>{t("独立创始人并不讨厌写作。他们讨厌的是，把同一条更新换四种方式再写一遍。","Solo founders don’t hate writing. They hate writing the same update four different ways.")}</blockquote><div class="draft-structure"><span>01</span><p>{t("第一句直接戳破重复改稿的厌倦感","Lead with a sharp contrarian hook on repeated labor")}</p><span>02</span><p>{t("用短句编号串起工作流与真实限制","Unpack the workflow and limits as a tight numbered thread")}</p></div><div class="draft-conclusion">{t("反差短句破题 · 编号串推演","Punchy hook · Numbered thread")}</div></article><article class="channel-draft"><div class="draft-top"><span class="channel-mark linkedin-mark">in</span><strong>LinkedIn</strong><span class="draft-label">{t("草稿译文","Draft excerpt")}</span></div><blockquote>{t("很多独立创始人只在一个平台发布，其他平台就慢慢放下了。<br><br>倒也谈不上懒，时间就这么多，分不过来。","Most solo founders publish one platform and quietly abandon the rest.<br><br>Not from laziness. From arithmetic.")}</blockquote><div class="draft-structure"><span>01</span><p>{t("先从一人团队的时间算术题建立同行共鸣","Open with the founder’s time-arithmetic dilemma")}</p><span>02</span><p>{t("再娓娓展开背后的工作方式与产品取舍","Build into operational lessons and product trade-offs")}</p></div><div class="draft-conclusion">{t("处境共鸣开场 · 叙事式展开","Situational empathy · Narrative arc")}</div></article></div><p class="channel-takeaway">{t("开场钩子与段落骨架随社区彻底变形，底层事实边界与审校入口寸步不让","Hooks and narrative spines reshape per feed; factual boundaries and review controls stay locked")}</p></article>'
    html+=f'<article class="channel-study" id="honest-states"><div class="case-subhead"><span class="eyebrow">03 / {t("诚实的异常状态","Honest states")}</span><h3>{t("我亲手删掉了两样<br>让路演更好看的东西","I deleted two features<br>that made stage demos look smoother")}</h3><p>{t("这两处删改在静态截图里几乎看不出功劳，上台演示时甚至少了点“圆满感”。但我必须砍——用户的账号攒了好几年口碑，真要因为界面报喜不报忧发出一篇错稿，砸的是真招牌。","Neither cut flatters a static screenshot, and both made live demos riskier. I cut them anyway. People spend years building trust on an account; if a flattering UI masks a flawed draft, the damage lands on them in public.")}</p></div><div class="decision-list">'+''.join(f'<div class="decision-row"><span>0{i+1}</span><h3>{h}</h3><p>{p}</p></div>' for i,(h,p) in enumerate([(t('一排撑场面的演示假数字','A row of flattering fake metrics'),t('初版总览页默认写着“42 条待发布、11 条待审核、18 条已排期”，猛一看像极了热闹的成熟 SaaS。可那串数字只是写死的演示数据——新用户刚注册进来看到满屏不属于自己的任务，第一反应只会是困惑与戒备。删的时候确实心疼了一下，但干净诚实的空状态，永远比借来的繁荣可信。','The first overview screen showed “42 queued, 11 in review, 18 scheduled.” It looked mature on stage—except the numbers were hardcoded demo filler. To a real new user, pre-filled counts immediately spark confusion and distrust. Deleting them stung for a second, yet an honest empty state beats borrowed maturity every time.')),(t('一份永远亮绿灯的静默兜底','A silent fallback that faked success'),t('早期为了防路演翻车，模型一旦超时报错，后台就会悄悄塞进一份通用模板，卡片照样显示“生成成功”。演示丝滑无比，真实用户却彻底蒙在鼓里：根本分不清哪篇真是针对这次更新写的，哪篇只是凑数的套话。现在哪张卡失败就坦白交代原因、支持单卡重试，绝不污染旁边已经跑通的草稿。','Early on, when a model failed, the system quietly slipped in a generic template and still marked the card green. Demos ran without a hitch—and real users had no way to tell genuine drafts from canned filler. Now a failed card states why and retries on its own, leaving every successful sibling card intact.'))]))+'</div></article>'
    details=[('agent-detail-'+short,t('冷启动先给落脚点，收起压迫感','Give first-time users an obvious foothold'),t('智能体首屏只留输入框与高频任务卡片，复杂面板按需展开，避免用户一进门就被全量配置吓退。','The Agent opens with one prompt bar and concrete starter tasks; secondary panels unfold on demand rather than crowding screen one.')),('review-detail-'+short,t('高频审改动作紧贴字面，低频项退后','Keep review actions right beside the words'),t('编辑与复制触手可及，次要参数收进二级区域，让视线始终钉在待核对的文案本身。','Edit and copy sit immediately on the card while secondary knobs step back—keeping eyes on the text under review.'))]
    html+='<div class="details-grid">'+''.join(f'<article class="detail-card"><div class="detail-image {"dark" if i else ""}">{image(asset,h)}</div><h3>{h}</h3><p>{p}</p></article>' for i,(asset,h,p) in enumerate(details))+'</div>'
